inline ::flatbuffers::Offset<Attribute> CreateAttribute(::flatbuffers::FlatBufferBuilder &_fbb,
                                                        const AttributeT *_o,
                                                        const ::flatbuffers::rehasher_function_t *_rehasher)
{
    (void)_rehasher;
    (void)_o;
    struct _VectorArgs {
        ::flatbuffers::FlatBufferBuilder *__fbb;
        const AttributeT *__o;
        const ::flatbuffers::rehasher_function_t *__rehasher;
    } _va = {&_fbb, _o, _rehasher};
    (void)_va;
    auto _name = _o->name.empty() ? 0 : _fbb.CreateString(_o->name);
    auto _ref_attr_name = _o->ref_attr_name.empty() ? 0 : _fbb.CreateString(_o->ref_attr_name);
    auto _doc_string = _o->doc_string.empty() ? 0 : _fbb.CreateString(_o->doc_string);
    auto _attr_type = _o->attr_type;
    auto _f = _o->f ? _o->f.get() : nullptr;
    auto _i = _o->i ? _o->i.get() : nullptr;
    auto _s = _o->s.size() ? _fbb.CreateVector(_o->s) : 0;
    auto _t = _o->t ? CreateTensor(_fbb, _o->t.get(), _rehasher) : 0;
    auto _g = _o->g ? CreateGraph(_fbb, _o->g.get(), _rehasher) : 0;
    auto _tp = _o->tp ? CreateTypeInfo(_fbb, _o->tp.get(), _rehasher) : 0;
    auto _floats = _o->floats.size() ? _fbb.CreateVector(_o->floats) : 0;
    auto _ints = _o->ints.size() ? _fbb.CreateVector(_o->ints) : 0;
    auto _strings = _o->strings.size() ? _fbb.CreateVectorOfStrings(_o->strings) : 0;
    auto _tensors = _o->tensors.size()
        ? _fbb.CreateVector<::flatbuffers::Offset<FlatBuffers::Dl::Tensor>>(
              _o->tensors.size(),
              [](size_t i, _VectorArgs *__va) {
                  return CreateTensor(*__va->__fbb, __va->__o->tensors[i].get(), __va->__rehasher);
              },
              &_va)
        : 0;
    auto _graphs = _o->graphs.size()
        ? _fbb.CreateVector<::flatbuffers::Offset<FlatBuffers::Dl::Graph>>(
              _o->graphs.size(),
              [](size_t i, _VectorArgs *__va) {
                  return CreateGraph(*__va->__fbb, __va->__o->graphs[i].get(), __va->__rehasher);
              },
              &_va)
        : 0;
    auto _type_protos = _o->type_protos.size()
        ? _fbb.CreateVector<::flatbuffers::Offset<FlatBuffers::Dl::TypeInfo>>(
              _o->type_protos.size(),
              [](size_t i, _VectorArgs *__va) {
                  return CreateTypeInfo(*__va->__fbb, __va->__o->type_protos[i].get(), __va->__rehasher);
              },
              &_va)
        : 0;
    return FlatBuffers::Dl::CreateAttribute(_fbb,
                                            _name,
                                            _ref_attr_name,
                                            _doc_string,
                                            _attr_type,
                                            _f,
                                            _i,
                                            _s,
                                            _t,
                                            _g,
                                            _tp,
                                            _floats,
                                            _ints,
                                            _strings,
                                            _tensors,
                                            _graphs,
                                            _type_protos);
}

